class Solution {
public:
    long long kthLargestLevelSum(TreeNode* root, int k) {
        if (!root) return -1;
        std::queue<TreeNode*> q;
        q.push(root);
        std::vector<long long> level_sums;
        while (!q.empty()) {
            int sz = q.size();
            long long sum = 0;
            for (int i = 0; i < sz; ++i) {
                TreeNode* node = q.front();
                q.pop();
                sum += node->val;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            level_sums.push_back(sum);
        }
        if ((int)level_sums.size() < k) return -1;
        std::sort(level_sums.begin(), level_sums.end(), std::greater<long long>());
        return level_sums[k - 1];
    }
};

class Solution {
    public long kthLargestLevelSum(TreeNode root, int k) {
        if (root == null) return -1;
        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();
        q.offer(root);
        java.util.List<Long> levelSums = new java.util.ArrayList<>();
        while (!q.isEmpty()) {
            int sz = q.size();
            long sum = 0;
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                sum += node.val;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            levelSums.add(sum);
        }
        if (levelSums.size() < k) return -1;
        java.util.Collections.sort(levelSums, java.util.Collections.reverseOrder());
        return levelSums.get(k - 1);
    }
}

